{
  "name": "opencode-claude-code-memory",
  "version": "0.1.6",
  "description": "OpenCode plugin for Claude Code memory that loads local Claude Code memory into OpenCode sessions and syncs updates back to the same memory files.",
  "keywords": [
    "opencode",
    "opencode-ai",
    "opencode-plugin",
    "claude-code",
    "claude-code-memory",
    "claude-memory",
    "anthropic-claude",
    "persistent-memory",
    "ai-coding-agent",
    "terminal-ai",
    "developer-tools"
  ],
  "homepage": "https://github.com/ngvoicu/opencode-claude-code-memory",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ngvoicu/opencode-claude-code-memory.git"
  },
  "bugs": {
    "url": "https://github.com/ngvoicu/opencode-claude-code-memory/issues"
  },
  "license": "MIT",
  "author": "Gabriel Voicu",
  "publishConfig": {
    "access": "public"
  },
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": "./index.js"
  },
  "files": [
    "index.js",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "check": "node --check index.js",
    "test": "node --test",
    "verify": "npm run check && npm run test"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.3.17"
  }
}
